class LinkedStack:
    class _Node:
        def __init__(self, value):
            self.value = value
            self.next = None

    def __init__(self):
        self.top = None

    def push(self, item):
        node = LinkedStack._Node(item)
        node.next = self.top
        self.top = node

    def pop(self):
        if self.top is None:
            raise IndexError("pop from empty stack")
        value = self.top.value
        self.top = self.top.next
        return value

    def peek(self):
        if self.top is None:
            raise IndexError("peek from empty stack")
        return self.top.value

    def is_empty(self):
        return self.top is None

